eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   translations: () => (/* binding */ translations)\n/* harmony export */ });\nconst translations = {\n    tr: {\n        // Navigation\n        navAbout: \"Hakkımda\",\n        navProjects: \"Projeler\",\n        navBlog: \"Blog\",\n        // Hero Section\n        heroBio: \"Software Developer & Designer // Merging code with design aesthetics // Exploring AI & building digital products\",\n        sendEmail: \"E-Posta G\\xf6nder\",\n        // About Page\n        aboutIntro: 'Merhaba, ben \\xd6mer Asaf. İşin teknik mimarisini estetikle birleştirmeyi seven, İstanbul merkezli bir Product Developer ve Sistem Mimarıyım. Benim i\\xe7in bir projenin sadece \"\\xe7alışması\" yetmez; sağlam bir temele ve kusursuz bir aray\\xfcze sahip olması gerekir. Aşağıdan eğitimime ve kullandığım teknolojilere g\\xf6z atabilirsin.',\n        aboutPs: \"P.S. Standart bir geliştirici değil, kendi \\xfcr\\xfcnlerini sıfırdan tasarlayan ve inşa eden biriyim.\",\n        aboutFooterQuote: \"Algoritmalarla geleceği tahmin etme, estetikle onu baştan tasarla\",\n        // Experiences\n        exp1Title: \"İstanbul \\xdcniversitesi\",\n        exp1Period: \"2024—2026\",\n        exp1Subtitle: \"Bilgisayar Programcılığı — Makine \\xd6ğrenmesi & Sistem Analizi\",\n        exp1Desc: \"Sistem analizi y\\xf6ntemleri, veri yapıları ve makine \\xf6ğrenmesi algoritmaları \\xfczerine teorik ve pratik uzmanlaşma. İşin matematiksel arka planını modern uygulama pratikleriyle entegre etme.\",\n        exp2Title: \"CodeVocab AI\",\n        exp2Period: \"2025—G\\xfcn\\xfcm\\xfcz\",\n        exp2Subtitle: \"Kurucu & Geliştirici — AI Destekli Kodlama ve Yazılım Mimarisi\",\n        exp2Desc: \"İngilizce \\xe7alışırken 'Acaba bu c\\xfcmleyi doğru mu kurdum?' ikilemini bitiriyoruz. Yazdığınız veya \\xe7alıştığınız İngilizce c\\xfcmleleri anında teyit etmenizi sağlayan yeni platformum: CodeVocab\",\n        exp3Title: \"Marki Corp.\",\n        exp3Period: \"2022—G\\xfcn\\xfcm\\xfcz\",\n        exp3Subtitle: \"Kurucu & Product Developer — Dijital \\xdcr\\xfcn St\\xfcdyosu\",\n        exp3Desc: \"Fikir aşamasından market sunumuna kadar olan t\\xfcm tasarım, aray\\xfcz mimarisi ve altyapı geliştirme s\\xfcre\\xe7lerinin \\xfcstlenilmesi. Ka\\xe7ış Alanı F1 ve diğer bağımsız \\xfcr\\xfcnlerin hayata ge\\xe7irilmesi.\",\n        // Projects Page & Cards\n        projectInspect: \"Projeyi İncele\",\n        projectNoLink: \"Detaylı link mevcut değil\",\n        projectWebsite: \"Web Sitesi\",\n        projectGithub: \"GitHub Deposu\",\n        projectInstagram: \"Instagram Profili\",\n        projCodeVocabDesc: 'İngilizce \\xe7alışırken \"Acaba bu c\\xfcmleyi doğru mu kurdum?\" ikilemini bitiriyoruz. Yazdığınız veya \\xe7alıştığınız İngilizce c\\xfcmleleri anında teyit etmenizi sağlayan yeni platformum: CodeVocab',\n        projCodeVocabDetailed: 'İngilizce \\xe7alışırken \"Acaba bu c\\xfcmleyi doğru mu kurdum?\" ikilemini bitiriyoruz. Yazdığınız veya \\xe7alıştığınız İngilizce c\\xfcmleleri anında teyit etmenizi sağlayan yeni platformum: CodeVocab. Doğal dil işleme (NLP) ve yapay zeka modelleriyle t\\xfcm teknik ve genel c\\xfcmle yapılarını analiz eder.',\n        projNeonDesc: \"Neon Oto Kurtarma i\\xe7in hazırlanan modern kurumsal web sitesi ve grafik/logo tasarımı.\",\n        projNeonDetailed: \"Neon Oto Kurtarma i\\xe7in \\xf6zel olarak kurgulanan kurumsal kimlik, logo tasarımı ve modern web sitesi projesi. Grafik tasarım aşamasından canlıya alınma s\\xfcrecine kadar t\\xfcm adımlar markanın sekt\\xf6rdeki dijital g\\xf6r\\xfcn\\xfcrl\\xfcğ\\xfcn\\xfc maksimuma \\xe7ıkarmak \\xfczere tasarlandı.\",\n        projCvsDesc: \"Doğru akademik \\xe7alışma, \\xf6zg\\xfcvenli iletişim ve etkili İngilizce becerileri i\\xe7in tasarlanmış sistemli bir \\xf6ğretim modeli.\",\n        projCvsDetailed: \"Doğru akademik \\xe7alışma, \\xf6zg\\xfcvenli iletişim ve etkili İngilizce becerileri i\\xe7in tasarlanmış sistemli bir \\xf6ğretim sistemi. IELTS, PTE ve TOEFL gibi sınavların yanı sıra kariyeriniz i\\xe7in profesyonel konuşmaya y\\xf6nelik en iyi y\\xf6ntemleri i\\xe7erir.\",\n        projKacisDesc: \"Formula 1 yarış analizleri, g\\xfcncel telemetri verileri ve minimalist infografikler paylaşan pop\\xfcler Instagram topluluğu: @kacisalanif1\",\n        projKacisDetailed: \"Formula 1 yarış analizleri, g\\xfcncel telemetri verileri ve minimalist infografikler paylaşan pop\\xfcler Instagram topluluğu. Yarış hafta sonlarının lastik stratejilerini, sıralama analizlerini ve telemetri verilerini estetik ve sade bir g\\xf6rsel dile indirgeyerek takip\\xe7ilerine sunar.\",\n        projZerpDesc: \"Bireysel kullanıcılar i\\xe7in geliştirilmiş minimalist finansal takip ve b\\xfct\\xe7e y\\xf6netim sistemi.\",\n        projZerpDetailed: \"Bireysel kullanıcılar i\\xe7in \\xf6zel olarak geliştirilmiş minimalist finansal takip ve b\\xfct\\xe7e y\\xf6netim sistemi. Gelir-gider dengesi, b\\xfct\\xe7e planlama ve finansal analiz ara\\xe7ları sunar. Şu anda kullanıma a\\xe7ık olmayan kapalı bir sistem olup, sadece konsept tanıtımı yapılmaktadır.\",\n        projFocusValleyDesc: \"Kullanıcıların 25, 30 ve 50 dakikalık periyotlarla odaklanmasını sağlayan ve odaklandık\\xe7a kazanılan sanal birikimlerle sanal m\\xfclkler edinilen oyunlaştırma tabanlı odaklanma platformu.\",\n        projFocusValleyDetailed: \"Focus Valley, dikkatinizi toplama s\\xfcre\\xe7lerinizi oyunlaştırma (gamification) mekanikleriyle birleştiren yeni nesil bir odaklanma platformudur. Kullanıcılar 25, 30 ve 50 dakikalık optimize edilmiş periyotlarda odaklanarak sanal gelir elde eder ve bu birikimlerle dijital ekosistemde ev, araba gibi sanal m\\xfclkler edinebilirler. Not: Proje şu an prototip aşamasındadır, canlı veri akışı veya aktif veri tabanı bulunmamaktadır.\",\n        // Blog\n        blogTitle: \"D\\xfcş\\xfcnceler & Notlar\",\n        blogDesc: \"Teknoloji, tasarım, yatırım ve sistemler \\xfczerine derinlemesine analizler.\",\n        blogReadTime: \"dakika\",\n        blogBackToTop: \"Yukarı Git\",\n        blogShare: \"Paylaş\",\n        blogShareSuccess: \"Bağlantı panoya kopyalandı!\",\n        blogNextPost: \"Sıradaki Yazı\",\n        blogBack: \"Blog'a Geri D\\xf6n\",\n        // Footer\n        footerLinkedIn: \"LinkedIn\",\n        footerMail: \"E-Posta\",\n        footerResume: \"\\xd6zge\\xe7miş (CV)\",\n        footerGithub: \"GitHub\",\n        footerDribbble: \"Dribbble\",\n        footerLiveSite: \"Canlı Site\",\n        footerRss: \"RSS Beslemesi\",\n        footerTwitter: \"X (Twitter)\",\n        footerNewsletterTitle: \"E-B\\xfclten\",\n        footerNewsletterDesc: \"Yeni yazılardan ve projelerden anında haberdar ol.\",\n        footerNewsletterPlaceholder: \"E-posta adresiniz\",\n        footerSubscribe: \"Abone Ol\",\n        footerSubscribeSuccess: \"Kayıt Başarılı!\",\n        // Ticker Action links\n        tickerSubscribe: \"B\\xdcLTENE ABONE OL\",\n        tickerFollowX: \"X'TE TAKİP ET\",\n        tickerRss: \"RSS BESLEMESİNİ OKU\",\n        tickerLinkedin: \"LINKEDIN'DEN BAĞLAN\",\n        // Editorial Desk\n        readAndSubscribe: \"OKU & ABONE OL\",\n        newsletterJoin: \"Katıl\",\n        notebookQuote: \"Bi\\xe7im işlevi takip eder.\",\n        // Connect\n        connectTitle: \"CONNECT\",\n        connectPs: \"P.S. Teknoloji veya tasarım s\\xfcre\\xe7leri hakkında konuşmak/yardım almak istersen ulaşmaktan \\xe7ekinme.\",\n        connectTechPs: \"P.S. A\\xe7ık kaynak projelerim, kod mimarisi veya yazılım teknolojileri hakkında konuşmak istersen ulaşmaktan \\xe7ekinme.\",\n        // Curations Gallery\n        galleryTitle: \"SE\\xc7KİLERİM\",\n        curation1Title: \"John Wick: Chapter 4\",\n        curation1Desc: \"John Wick'in Y\\xfcksek Masa'ı yenmek i\\xe7in \\xe7ıktığı intikam yolculuğunda, eski dostlarını d\\xfcşmana \\xe7eviren k\\xfcresel g\\xfc\\xe7lere karşı m\\xfccadelesi.\",\n        curation2Title: \"Yeraltından Notlar\",\n        curation2Desc: \"Dostoyevski'nin varoluş\\xe7u felsefesinin temellerini atan, insanın i\\xe7sel \\xe7atışmalarını ve toplum dışılığını anlatan k\\xfclt eseri.\",\n        curation3Title: \"Ben G\\xfczelden Anlarım\",\n        curation3Desc: \"Kenan Doğulu'nun 1999 \\xe7ıkışlı 'Ben Senin Her Şeyinim' alb\\xfcm\\xfcnde yer alan, s\\xf6z ve m\\xfcziği kendisine ait olan pop\\xfcler klasiği.\"\n    },\n    en: {\n        // Navigation\n        navAbout: \"About me\",\n        navProjects: \"Projects\",\n        navBlog: \"Blog\",\n        // Hero Section\n        heroBio: \"Software Developer & Designer // Merging code with design aesthetics // Exploring AI & building digital products\",\n        sendEmail: \"Send Email\",\n        // About Page\n        aboutIntro: \"Hello, I'm \\xd6mer Asaf. I'm an Istanbul-based Product Developer and Systems Architect who loves combining technical architecture with design aesthetics. For me, a project shouldn't just \\\"work\\\"; it must have a solid foundation and a flawless interface. You can explore my education and technical stack below.\",\n        aboutPs: \"P.S. I am not a standard developer; I design and build my own products from scratch.\",\n        aboutFooterQuote: \"Predict the future with algorithms, redesign it with aesthetics\",\n        // Experiences\n        exp1Title: \"Istanbul University\",\n        exp1Period: \"2024—2026\",\n        exp1Subtitle: \"Computer Programming — Machine Learning & Systems Analysis\",\n        exp1Desc: \"Theoretical and practical specialization in systems analysis methodologies, data structures, and machine learning algorithms. Integrating mathematical backgrounds with modern software engineering practices.\",\n        exp2Title: \"CodeVocab AI\",\n        exp2Period: \"2025—Present\",\n        exp2Subtitle: \"Founder & Developer — AI-Assisted Coding & Software Architecture\",\n        exp2Desc: \"We eliminate the 'Did I form this sentence correctly?' dilemma while studying English. My new platform, CodeVocab, allows you to instantly verify English sentences you write or study.\",\n        exp3Title: \"Marki Corp.\",\n        exp3Period: \"2022—Present\",\n        exp3Subtitle: \"Founder & Product Developer — Digital Product Studio\",\n        exp3Desc: \"Handling the end-to-end process from launch, including product design, interface architecture, and infrastructure development. Bringing Ka\\xe7ış Alanı F1 and other indie products to life.\",\n        // Projects Page & Cards\n        projectInspect: \"Inspect Project\",\n        projectNoLink: \"Detailed link not available\",\n        projectWebsite: \"Website\",\n        projectGithub: \"GitHub Repository\",\n        projectInstagram: \"Instagram Profile\",\n        projCodeVocabDesc: \"We eliminate the 'Did I form this sentence correctly?' dilemma while studying English. My new platform, CodeVocab, allows you to instantly verify English sentences.\",\n        projCodeVocabDetailed: \"We eliminate the 'Did I form this sentence correctly?' dilemma while studying English. My new platform, CodeVocab, allows you to instantly verify English sentences. Powered by natural language processing (NLP) and AI models to analyze syntax and grammar.\",\n        projNeonDesc: \"Modern corporate website and graphic/logo design developed for Neon Auto Recovery.\",\n        projNeonDetailed: \"Corporate identity, logo design, and custom website developed for Neon Auto Recovery. Every step, from graphics to deployment, was optimized to maximize the brand's digital visibility.\",\n        projCvsDesc: \"A systematic teaching model designed for academic study, confident communication, and effective English skills.\",\n        projCvsDetailed: \"A systematic curriculum designed for academic excellence, confident communication, and language fluency. Features custom strategies for IELTS, PTE, TOEFL, and professional speech.\",\n        projKacisDesc: \"A popular Formula 1 Instagram community sharing race analyses, telemetry data, and minimalist infographics: @kacisalanif1\",\n        projKacisDetailed: \"A popular Formula 1 Instagram community sharing race analyses, telemetry data, and minimal infographics. Translates complex telemetry and tire strategies into beautiful, clean graphics.\",\n        projZerpDesc: \"A minimalist personal financial tracker and budget management application.\",\n        projZerpDetailed: \"A minimalist personal financial tracker and budget management application. Features income-expense logs, budget planning, and basic financial analysis. Currently a closed concept layout.\",\n        projFocusValleyDesc: \"A gamified focus platform allowing users to concentrate in 25, 30, and 50-minute periods, earning virtual currency to purchase assets like virtual houses and cars.\",\n        projFocusValleyDetailed: \"Focus Valley is a next-generation productivity and focus platform that integrates core concentration techniques with gamification mechanics. Users commit to optimized focus intervals of 25, 30, and 50 minutes to generate virtual rewards, which can be spent to acquire digital assets like virtual estates, vehicles, and items. Note: This project is currently in the prototype phase, and no live database or user data integration is active.\",\n        // Blog\n        blogTitle: \"Thoughts & Notes\",\n        blogDesc: \"In-depth analyses on technology, design, investment, and systems.\",\n        blogReadTime: \"min\",\n        blogBackToTop: \"Back to Top\",\n        blogShare: \"Share\",\n        blogShareSuccess: \"Link copied to clipboard!\",\n        blogNextPost: \"Next Post\",\n        blogBack: \"Back to Blog\",\n        // Footer\n        footerLinkedIn: \"LinkedIn\",\n        footerMail: \"Email\",\n        footerResume: \"Resume (CV)\",\n        footerGithub: \"GitHub\",\n        footerDribbble: \"Dribbble\",\n        footerLiveSite: \"Live Site\",\n        footerRss: \"RSS Feed\",\n        footerTwitter: \"X (Twitter)\",\n        footerNewsletterTitle: \"Newsletter\",\n        footerNewsletterDesc: \"Get notified about new articles and projects instantly.\",\n        footerNewsletterPlaceholder: \"Your email address\",\n        footerSubscribe: \"Subscribe\",\n        footerSubscribeSuccess: \"Subscribed Successfully!\",\n        // Ticker Action links\n        tickerSubscribe: \"SUBSCRIBE TO NEWSLETTER\",\n        tickerFollowX: \"FOLLOW ON X\",\n        tickerRss: \"READ RSS FEED\",\n        tickerLinkedin: \"CONNECT ON LINKEDIN\",\n        // Editorial Desk\n        readAndSubscribe: \"READ & SUBSCRIBE\",\n        newsletterJoin: \"Join\",\n        notebookQuote: \"Form follows function.\",\n        // Connect\n        connectTitle: \"CONNECT\",\n        connectPs: \"P.S. If you're trying to get into tech or product design/management, feel free to reach out. I'd love to help.\",\n        connectTechPs: \"P.S. If you want to talk about open source projects, code architecture, or software engineering, feel free to reach out.\",\n        // Curations Gallery\n        galleryTitle: \"CURATIONS\",\n        curation1Title: \"John Wick: Chapter 4\",\n        curation1Desc: \"John Wick uncovers a path to defeating The High Table, facing off against new enemies and global forces that turn old friends into foes.\",\n        curation2Title: \"Notes from Underground\",\n        curation2Desc: \"Dostoevsky's cult novel that lays the foundations of existentialist philosophy, depicting human internal conflict and alienation.\",\n        curation3Title: \"Ben G\\xfczelden Anlarım\",\n        curation3Desc: \"Kenan Doğulu's popular classic from his 1999 album 'Ben Senin Her Şeyinim', written and composed by himself.\"\n    }\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/lib/translations.ts\n");

